from pathlib import Path

p=Path('index.html')
html=p.read_text(encoding='utf-8')
if 'id="postDraftAnalysis"' in html:
    print('Post-draft analysis already injected')
    raise SystemExit

css='''<style>
.post-analysis{margin-top:20px;padding:24px;border:1px solid #2a3a59;border-radius:24px;background:linear-gradient(145deg,#0a121f,#12172a)}
.post-head{display:flex;justify-content:space-between;gap:16px;align-items:end;flex-wrap:wrap}.post-head h3{margin:5px 0;font-size:28px}.post-head p{margin:0;color:#8d9bb7;max-width:720px;line-height:1.55}.post-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.post-team{border:1px solid #24334e;border-radius:18px;padding:17px;background:#0a101c}.post-team.blue{box-shadow:inset 3px 0 #4ca7ff}.post-team.red{box-shadow:inset -3px 0 #ff6b7d}.post-team h4{margin:0 0 12px;font-size:18px}.post-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.post-metric{padding:10px;border:1px solid #263550;border-radius:12px;background:#0d1625}.post-metric b{display:block;font-size:14px}.post-metric span{font-size:9px;color:#8290aa;letter-spacing:.06em}.post-block{margin-top:14px}.post-block strong{display:block;margin-bottom:7px;font-size:12px;color:#d7e2f4}.post-list{display:grid;gap:7px}.post-item{padding:10px 11px;border:1px solid #293852;border-radius:11px;background:#0b1321;color:#aebbd1;font-size:12px;line-height:1.45}.post-item.good{border-color:#2e6b56;color:#a5ecc6}.post-item.warn{border-color:#72592e;color:#ffd98b}.post-summary{margin-top:16px;padding:16px;border:1px solid #2b3c59;border-radius:16px;background:#0b1322}.post-summary h4{margin:0 0 8px}.post-summary p{margin:0;color:#9aa8c1;line-height:1.6;font-size:13px}.post-note{margin-top:12px;color:#6f7f99;font-size:11px;line-height:1.55}@media(max-width:760px){.post-grid{grid-template-columns:1fr}.post-metrics{grid-template-columns:1fr 1fr}}
</style>'''
html=html.replace('</head>',css+'</head>')

markup='''<section id="postDraftAnalysis" class="post-analysis"><div class="post-head"><div><small>POST-DRAFT ANALYSIS</small><h3>¿Qué pide cada composición?</h3><p>Lectura editorial de estructura, herramientas y condiciones de victoria. No es una predicción probabilística del resultado.</p></div></div><div class="post-grid"><article class="post-team blue"><h4>Blue</h4><div id="postBlueMetrics" class="post-metrics"></div><div class="post-block"><strong>Fortalezas</strong><div id="postBlueStrengths" class="post-list"></div></div><div class="post-block"><strong>Riesgos</strong><div id="postBlueRisks" class="post-list"></div></div><div class="post-block"><strong>Condición de victoria</strong><div id="postBlueWin" class="post-list"></div></div></article><article class="post-team red"><h4>Red</h4><div id="postRedMetrics" class="post-metrics"></div><div class="post-block"><strong>Fortalezas</strong><div id="postRedStrengths" class="post-list"></div></div><div class="post-block"><strong>Riesgos</strong><div id="postRedRisks" class="post-list"></div></div><div class="post-block"><strong>Condición de victoria</strong><div id="postRedWin" class="post-list"></div></div></article></div><div class="post-summary"><h4>Lectura comparativa</h4><p id="postSummaryText">Completa al menos algunos picks de ambos equipos para generar el análisis.</p></div><p class="post-note">Las etiquetas son editoriales y describen funciones de draft. No representan tasas de victoria, matchup estadístico ni datos oficiales de torneo.</p></section>'''
needle='<p class="turn-note">Secuencia simplificada de draft competitivo para entrenamiento. Picks y bans usados quedan bloqueados. Las recomendaciones son editoriales, no predicciones de victoria.</p></div>'
if needle not in html:
    raise RuntimeError('Turn draft block not found')
html=html.replace(needle,needle+markup)

js=r'''<script>
(()=>{
const PROFILE={
'Aulus':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:1,poke:0},'Rafaela':{front:0,engage:0,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Masha':{front:1,engage:1,sustain:1,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:0,poke:0},'Marcel':{front:0,engage:1,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Argus':{front:0,engage:0,sustain:1,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:1,poke:0},'Minotaur':{front:1,engage:1,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Khufra':{front:1,engage:1,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Floryn':{front:0,engage:0,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Gloo':{front:1,engage:1,sustain:1,peel:0,phys:0,magic:1,dive:1,wave:1,scaling:0,poke:0},'Carmilla':{front:1,engage:1,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Obsidia':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:0,wave:1,scaling:1,poke:0},'Hirara':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:1,wave:0,scaling:0,poke:0},'Estes':{front:0,engage:0,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Popol & Kupa':{front:0,engage:1,sustain:0,peel:1,phys:1,magic:0,dive:0,wave:1,scaling:0,poke:0},'Lolita':{front:1,engage:1,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Valir':{front:0,engage:0,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:1},'Diggie':{front:0,engage:0,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:0},'Bruno':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:0,wave:1,scaling:1,poke:0},'Lukas':{front:1,engage:1,sustain:1,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:0,poke:0},'Gord':{front:0,engage:0,sustain:0,peel:0,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:1},'Edith':{front:1,engage:1,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:0},'Cyclops':{front:0,engage:0,sustain:0,peel:0,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:0},'Belerick':{front:1,engage:1,sustain:1,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Ruby':{front:1,engage:1,sustain:1,peel:1,phys:1,magic:0,dive:0,wave:1,scaling:0,poke:0},'Hanabi':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:0,wave:1,scaling:1,poke:0},'Eudora':{front:0,engage:1,sustain:0,peel:0,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:0},'Granger':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:0,poke:1},'Hayabusa':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:0,poke:0},'Nolan':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:1,wave:1,scaling:0,poke:0},'Tigreal':{front:1,engage:1,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:0,scaling:0,poke:0},'Xavier':{front:0,engage:0,sustain:0,peel:1,phys:0,magic:1,dive:0,wave:1,scaling:1,poke:1},'Ixia':{front:0,engage:0,sustain:0,peel:0,phys:1,magic:0,dive:0,wave:1,scaling:1,poke:0},'Fredrinn':{front:1,engage:1,sustain:1,peel:1,phys:1,magic:0,dive:0,wave:1,scaling:0,poke:0},'Pharsa':{front:0,engage:0,sustain:0,peel:0,phys:0,magic:1,dive:0,wave:1,scaling:0,poke:1}}
function picksFrom(side){const root=document.getElementById(side==='blue'?'blueSlots':'redSlots');if(!root)return[];return [...root.querySelectorAll('.turn-slot')].filter(x=>x.querySelector('span')?.textContent.includes('PICK')).map(x=>x.querySelector('b')?.textContent).filter(x=>x&&x!=='—')}
function sum(team,k){return team.reduce((a,n)=>a+(PROFILE[n]?.[k]||0),0)}
function metrics(team){return {front:sum(team,'front'),engage:sum(team,'engage'),peel:sum(team,'peel'),sustain:sum(team,'sustain'),phys:sum(team,'phys'),magic:sum(team,'magic'),wave:sum(team,'wave'),dive:sum(team,'dive'),scaling:sum(team,'scaling'),poke:sum(team,'poke')}}
function identity(m){if(m.poke>=2&&m.engage===0)return'Poke / control de espacio';if(m.dive>=2)return'Dive / acceso a backline';if(m.sustain>=2)return'Sustain / peleas largas';if(m.front>=2&&m.scaling>=2)return'Front-to-back / escalado';if(m.engage>=2)return'Engage / teamfight';return'Composición híbrida'}
function difficulty(m){let d=2;if(m.engage===0)d++;if(m.front===0)d++;if(m.dive>=2)d++;if(m.poke>=2)d++;return d>=5?'Alta':d>=4?'Media-alta':d>=3?'Media':'Baja-media'}
function build(team){const m=metrics(team),strength=[],risk=[],win=[];if(!team.length)return{m,strength:['Aún sin picks suficientes.'],risk:['Completa el draft para evaluar riesgos.'],win:['Sin condición definida todavía.'],id:'Sin definir',diff:'—'};if(m.front>=1)strength.push('Tiene frontline para crear espacio.');if(m.engage>=1)strength.push('Cuenta con iniciación clara.');if(m.peel>=1)strength.push('Tiene herramientas para proteger carries.');if(m.sustain>=1)strength.push('Puede sostener peleas más largas.');if(m.phys>=1&&m.magic>=1)strength.push('Daño mixto, más difícil de itemizar en contra.');if(m.wave>=3)strength.push('Buen control de oleadas y prioridad.');if(m.dive>=2)strength.push('Amenaza fuerte sobre la retaguardia rival.');if(m.poke>=2)strength.push('Puede desgastar antes de comprometerse.');if(m.front<1)risk.push('Sin frontline clara: puede perder espacio en objetivos.');if(m.engage<1)risk.push('Le cuesta forzar peleas por iniciativa propia.');if(m.peel<1)risk.push('Backline expuesta frente a dive rival.');if(m.magic<1)risk.push('Daño casi totalmente físico.');if(m.phys<1)risk.push('Daño casi totalmente mágico.');if(m.wave<2)risk.push('Wave clear limitado para defender o preparar objetivos.');if(m.dive>=2)win.push('Buscar flancos y castigar carries aislados.');else if(m.poke>=2)win.push('Desgastar antes de entrar y pelear con ventaja de vida.');else if(m.sustain>=2)win.push('Extender peleas y ganar por recursos y curación.');else if(m.scaling>=2)win.push('Proteger el escalado y llegar ordenado al mid/late game.');else if(m.engage>=2)win.push('Forzar peleas rápidas alrededor de control y seguimiento.');else win.push('Jugar por tempo, objetivos y picks sobre errores rivales.');return{m,strength:strength.length?strength:['Estructura flexible, pero sin fortaleza dominante.'],risk:risk.length?risk:['Sin carencia estructural evidente.'],win,id:identity(m),diff:difficulty(m)}}
function renderTeam(side,data){const pref=side==='blue'?'postBlue':'postRed';const mm=data.m;document.getElementById(pref+'Metrics').innerHTML=[['Identidad',data.id],['Ejecución',data.diff],['Frontline',mm.front],['Engage',mm.engage],['Peel',mm.peel],['Sustain',mm.sustain],['Físico',mm.phys],['Mágico',mm.magic],['Dive',mm.dive]].map(([a,b])=>`<div class="post-metric"><b>${b}</b><span>${a.toUpperCase()}</span></div>`).join('');document.getElementById(pref+'Strengths').innerHTML=data.strength.map(x=>`<div class="post-item good">${x}</div>`).join('');document.getElementById(pref+'Risks').innerHTML=data.risk.map(x=>`<div class="post-item warn">${x}</div>`).join('');document.getElementById(pref+'Win').innerHTML=data.win.map(x=>`<div class="post-item">${x}</div>`).join('')}
function render(){const B=build(picksFrom('blue')),R=build(picksFrom('red'));renderTeam('blue',B);renderTeam('red',R);const bp=picksFrom('blue').length,rp=picksFrom('red').length;let txt;if(bp<3||rp<3)txt='Aún hay pocos picks para una comparación útil. El análisis ganará precisión editorial conforme avance el draft.';else{const easier=B.diff==='Baja-media'&&R.diff!=='Baja-media'?'Blue':R.diff==='Baja-media'&&B.diff!=='Baja-media'?'Red':null;txt=`Blue propone ${B.id.toLowerCase()}, mientras Red se orienta a ${R.id.toLowerCase()}. ${easier?easier+' parece más sencilla de ejecutar estructuralmente. ':''}La diferencia real dependerá de matchups, manos, tempo y macro, no solo de la forma del draft.`}document.getElementById('postSummaryText').textContent=txt}
const obs=new MutationObserver(render);['blueSlots','redSlots'].forEach(id=>{const el=document.getElementById(id);if(el)obs.observe(el,{childList:true,subtree:true,characterData:true})});render();
})();
</script>'''
html=html.replace('</body>',js+'</body>')
p.write_text(html,encoding='utf-8')
print('Injected post-draft analysis')
